# {{NAME}} installer - generated by vexelray-installer. Do not edit by hand; regenerate it.
#
#   irm {{INSTALL_URL}} | iex
#
# Options (set as environment variables before running the line above):
#   INSTALL_VERSION=1.2.3    install a specific version instead of the latest
#   INSTALL_DIR=C:\some\dir  install somewhere other than the default
#   INSTALL_NO_SHORTCUTS=1   skip the desktop / Start menu shortcuts
#   INSTALL_NO_PATH=1        do not add anything to the user PATH
#   INSTALL_NO_ASSOCIATIONS=1  do not register file types
#   INSTALL_FORCE=1          reinstall even if this version is already installed
#   INSTALL_SKIP_CHECKS=1    install even if this computer does not meet the system requirements
#   INSTALL_QUIET=1          no window: ask nothing and report in the console only
#
# Updates and reinstalls keep the NO_* choices of the last install; set one to 0 to opt back in.
#
# Run from a console a person is at, the installer opens a window where the folder and the NO_* choices
# can be changed, and shows its progress there as well as in the console. It stays in the console when
# INSTALL_QUIET is set, under CI, with -NonInteractive, or when its output is redirected.
#
# The same options are accepted as arguments when the script is run from a file:
#   -Version 1.2.3  -Dir C:\some\dir  -NoShortcuts  -NoPath  -NoAssociations  -Force  -SkipChecks  -Quiet

$InstallerCfg = '{{CONFIG_JSON}}' | ConvertFrom-Json

# The window, when there is one: ViUiLog copies console output into it, and is a no-op without it.
function ViUiLog([string]$m) {
    if ($ViUi -and -not $ViUi.Closed) { $ViUi.Log.AppendText("$m`r`n"); [Windows.Forms.Application]::DoEvents() }
}
function ViUiBar([int]$pct, $ui = $ViUi) {
    if (-not $ui -or $ui.Closed) { return }
    if ($pct -lt 0) { $ui.Bar.Style = 'Marquee' } else { $ui.Bar.Style = 'Continuous'; $ui.Bar.Value = [Math]::Min(100, $pct) }
}
function ViStep([string]$m) {
    Write-Host "==> $m" -ForegroundColor Cyan
    if ($ViUi -and -not $ViUi.Closed) { $ViUi.Status.Text = $m; ViUiBar -1 }
    ViUiLog $m
}
function ViInfo([string]$m) { Write-Host "    $m"; ViUiLog "    $m" }
function ViWarn([string]$m) { Write-Warning $m; ViUiLog "    Warning: $m" }
function ViSay([string]$m, [string]$color) {
    if ($color) { Write-Host $m -ForegroundColor $color } else { Write-Host $m }
    ViUiLog $m
}
function ViExpand([string]$p) { [Environment]::ExpandEnvironmentVariables($p) }
function ViSha([string]$p) { (Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLowerInvariant() }

function ViRegistryDir {
    if ($env:INSTALL_REGISTRY_DIR) { return $env:INSTALL_REGISTRY_DIR }
    ViExpand $InstallerCfg.registryDir
}

function ViGet([string]$url) {
    $c = (Invoke-WebRequest -UseBasicParsing -Uri $url).Content
    if ($c -is [byte[]]) { $c = [Text.Encoding]::UTF8.GetString($c) }
    $c
}

function ViWriteText([string]$path, [string]$text) {
    [IO.File]::WriteAllText($path, $text, (New-Object Text.UTF8Encoding $false))
}

function ViEnsureDir([string]$dir) {
    if ($dir -and -not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
}

# ---- user PATH (HKCU\Environment) ------------------------------------------------------

function ViBroadcastEnv {
    try {
        if (-not ('ViWin.ViNative' -as [type])) {
            Add-Type -Namespace ViWin -Name ViNative -MemberDefinition '[DllImport("user32.dll", SetLastError=true, CharSet=CharSet.Auto)] public static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint Msg, UIntPtr wParam, string lParam, uint fuFlags, uint uTimeout, out UIntPtr lpdwResult);'
        }
        $r = [UIntPtr]::Zero
        [ViWin.ViNative]::SendMessageTimeout([IntPtr]0xffff, 0x1A, [UIntPtr]::Zero, 'Environment', 2, 5000, [ref]$r) | Out-Null
    } catch { }
}

function ViUserPathGet {
    $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Environment')
    try { $k.GetValue('Path', '', [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames) } finally { $k.Close() }
}

function ViUserPathSet([string]$value) {
    $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Environment', $true)
    try {
        $kind = [Microsoft.Win32.RegistryValueKind]::ExpandString
        if ($k.GetValueNames() -contains 'Path') { $kind = $k.GetValueKind('Path') }
        $k.SetValue('Path', $value, $kind)
    } finally { $k.Close() }
    ViBroadcastEnv
}

function ViPathNorm([string]$p) { (ViExpand $p).TrimEnd('\').ToLowerInvariant() }

# Returns $true when the directory was added (i.e. it was not on the user PATH already).
function ViPathAdd([string]$dir) {
    $cur = [string](ViUserPathGet)
    foreach ($p in ($cur -split ';')) { if ($p -and (ViPathNorm $p) -eq (ViPathNorm $dir)) { return $false } }
    if ($cur -and -not $cur.EndsWith(';')) { $cur += ';' }
    ViUserPathSet ($cur + $dir)
    $env:Path = "$env:Path;$dir"
    return $true
}

function ViPathRemove([string]$dir) {
    $parts = @((ViUserPathGet) -split ';')
    $keep = @($parts | Where-Object { -not $_ -or (ViPathNorm $_) -ne (ViPathNorm $dir) })
    if ($keep.Count -ne $parts.Count) { ViUserPathSet ($keep -join ';') }
}

# ---- file associations (HKCU\Software\Classes) ------------------------------------------

function ViNotifyAssoc {
    try {
        if (-not ('ViWin.ViShell' -as [type])) {
            Add-Type -Namespace ViWin -Name ViShell -MemberDefinition '[DllImport("shell32.dll")] public static extern void SHChangeNotify(int wEventId, uint uFlags, IntPtr dwItem1, IntPtr dwItem2);'
        }
        [ViWin.ViShell]::SHChangeNotify(0x08000000, 0, [IntPtr]::Zero, [IntPtr]::Zero)
    } catch { }
}

# Writes the ProgID and lists it under the extension's OpenWithProgids ("Open with"). It becomes the
# extension's default only when neither the user's nor the machine's classes name one already; the
# record keeps whether it did, so removal clears only what this install set.
function ViAssocAdd($fa, [string]$command, [string]$icon) {
    $classes = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey('Software\Classes')
    try {
        $pk = $classes.CreateSubKey($fa.progId)
        try {
            $pk.SetValue('', [string]$fa.description)
            if ($icon) { $ik = $pk.CreateSubKey('DefaultIcon'); $ik.SetValue('', "$icon,0"); $ik.Close() }
            else { $pk.DeleteSubKeyTree('DefaultIcon', $false) }
            $ck = $pk.CreateSubKey('shell\open\command'); $ck.SetValue('', $command); $ck.Close()
        } finally { $pk.Close() }
        $ek = $classes.CreateSubKey($fa.extension)
        try {
            $ow = $ek.CreateSubKey('OpenWithProgids'); $ow.SetValue($fa.progId, ''); $ow.Close()
            $cur = [string]$ek.GetValue('')
            $isDefault = $cur -eq $fa.progId
            if (-not $cur) {
                $taken = $false
                $mk = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("Software\Classes\$($fa.extension)")
                if ($mk) { try { $taken = [bool]$mk.GetValue('') } finally { $mk.Close() } }
                if (-not $taken) { $ek.SetValue('', $fa.progId); $isDefault = $true }
            }
            $ctype = $null
            if ($isDefault -and $fa.contentType) {
                $have = [string]$ek.GetValue('Content Type')
                if (-not $have) { $ek.SetValue('Content Type', [string]$fa.contentType) }
                if (-not $have -or $have -eq $fa.contentType) { $ctype = [string]$fa.contentType }
            }
        } finally { $ek.Close() }
    } finally { $classes.Close() }
    [ordered]@{ extension = $fa.extension; progId = $fa.progId; isDefault = $isDefault; contentType = $ctype }
}

# Undoes ViAssocAdd for one install-record entry; leaves anything another program put on the extension.
function ViAssocRemove($a) {
    $classes = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software\Classes', $true)
    if (-not $classes) { return }
    try {
        $classes.DeleteSubKeyTree($a.progId, $false)
        $ek = $classes.OpenSubKey($a.extension, $true)
        if (-not $ek) { return }
        try {
            $ow = $ek.OpenSubKey('OpenWithProgids', $true)
            if ($ow) {
                try { $ow.DeleteValue($a.progId, $false); $owEmpty = $ow.ValueCount -eq 0 -and $ow.SubKeyCount -eq 0 } finally { $ow.Close() }
                if ($owEmpty) { $ek.DeleteSubKeyTree('OpenWithProgids', $false) }
            }
            if ([string]$ek.GetValue('') -eq $a.progId) { $ek.DeleteValue('', $false) }
            if ($a.contentType -and [string]$ek.GetValue('Content Type') -eq $a.contentType) { $ek.DeleteValue('Content Type', $false) }
            $extEmpty = $ek.ValueCount -eq 0 -and $ek.SubKeyCount -eq 0
        } finally { $ek.Close() }
        if ($extEmpty) { $classes.DeleteSubKeyTree($a.extension, $false) }
    } finally { $classes.Close() }
}

# ---- versions ---------------------------------------------------------------------------

function ViVerKey([string]$v) {
    $core = ($v -replace '^[vV]', '') -replace '[-+].*$', ''
    if ($core -notmatch '\.') { $core = "$core.0" }
    try { $ver = [version]$core } catch { $ver = [version]'0.0' }
    [pscustomobject]@{ Ver = $ver; Pre = [bool]($v -match '-') }
}

function ViCompare([string]$a, [string]$b) {
    $x = ViVerKey $a; $y = ViVerKey $b
    $c = $x.Ver.CompareTo($y.Ver)
    if ($c -ne 0) { return $c }
    if ($x.Pre -and -not $y.Pre) { return -1 }
    if (-not $x.Pre -and $y.Pre) { return 1 }
    return 0
}

# ---- java (only matters for uberjar binaries) ------------------------------------------

function ViFindJava([string]$exe) {
    $c = Get-Command $exe -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($c) { return $c.Source }
    if ($env:JAVA_HOME) {
        $p = Join-Path (Join-Path $env:JAVA_HOME 'bin') "$exe.exe"
        if (Test-Path -LiteralPath $p) { return $p }
    }
    return $null
}

function ViJavaMajor([string]$javaExe) {
    try {
        $o = (& cmd.exe /c "`"$javaExe`" -version 2>&1") -join ' '
        if ($o -match 'version "(\d+)(?:\.(\d+))?') {
            $m = [int]$Matches[1]
            if ($m -eq 1 -and $Matches[2]) { $m = [int]$Matches[2] }
            return $m
        }
    } catch { }
    return 0
}

# Authenticode check for a downloaded native executable, when the manifest says it is signed.
# With a pinned thumbprint a certificate Windows cannot chain to a trusted root (a self-signed one)
# is accepted if it is exactly that certificate; without one the signature must be trusted.
function ViCheckSignature([string]$path, $meta, [string]$label) {
    if (-not $meta) { return }
    $sig = Get-AuthenticodeSignature -LiteralPath $path
    $st = [string]$sig.Status
    if ($st -eq 'NotSigned') { throw "$label is not signed, but the manifest says it is signed by $($meta.subject). Nothing was installed." }
    if ($st -eq 'HashMismatch') { throw "$label was altered after it was signed. Nothing was installed." }
    $cert = $sig.SignerCertificate
    if (-not $cert) { throw "$label has no usable signature ($st). Nothing was installed." }
    if ($cert.Subject.IndexOf([string]$meta.subject, [StringComparison]::OrdinalIgnoreCase) -lt 0) {
        throw "$label is signed by $($cert.Subject), not $($meta.subject). Nothing was installed."
    }
    if ($meta.thumbprint) {
        if ($cert.Thumbprint -ne ([string]$meta.thumbprint).ToUpperInvariant()) {
            throw "$label is signed by a different certificate than the manifest pins ($($cert.Thumbprint)). Nothing was installed."
        }
        if ($st -ne 'Valid') { ViWarn "$label is signed by the pinned certificate $($cert.Thumbprint), which this machine does not trust ($st)." }
    } elseif ($st -ne 'Valid') {
        throw "$label has a signature from $($cert.Subject) that is not trusted ($st). Nothing was installed."
    }
    ViInfo "$label signed by $($cert.Subject)"
}

# Unpacks a zip, refusing entries that would land outside $dest.
function ViExpandZip([string]$zip, [string]$dest) {
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    ViEnsureDir $dest
    $root = [IO.Path]::GetFullPath($dest).TrimEnd('\') + '\'
    $z = [IO.Compression.ZipFile]::OpenRead($zip)
    try {
        foreach ($e in $z.Entries) {
            $p = [IO.Path]::GetFullPath((Join-Path $dest $e.FullName))
            if (-not $p.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) { throw "Archive entry would leave the target folder: $($e.FullName)" }
            if ($e.FullName.EndsWith('/') -or $e.FullName.EndsWith('\')) { ViEnsureDir $p; continue }
            ViEnsureDir (Split-Path $p -Parent)
            [IO.Compression.ZipFileExtensions]::ExtractToFile($e, $p, $true)
            if ($ViUi -and -not $ViUi.Closed) { [Windows.Forms.Application]::DoEvents() }
        }
    } finally { $z.Dispose() }
}

function ViReadRecord([string]$id) {
    $p = Join-Path (ViRegistryDir) "$id.json"
    if (Test-Path -LiteralPath $p) { try { return (Get-Content -Raw -LiteralPath $p | ConvertFrom-Json) } catch { } }
    return $null
}

function ViQuoteArg([string]$a) { if ($a -match '\s') { "`"$a`"" } else { $a } }

function ViJvmArgs($b) {
    $o = @()
    foreach ($a in @($b.jvmArgs)) { if ($a) { $o += (ViQuoteArg $a) } }
    return ($o -join ' ')
}

# The .cmd that starts a jar. With a runtime it reads <registryDir>\<runtime>.home (one line: that
# install's folder) every time, so updating the runtime never leaves launchers pointing at a stale JVM.
function ViJarLauncher($b, [string]$jarName) {
    $jvm = ViJvmArgs $b
    if ($jvm) { $jvm = " $jvm" }
    if ($b.runtime) {
        $ptr = Join-Path (ViRegistryDir) "$($b.runtime).home"
        return "@echo off`r`nsetlocal`r`nset `"VI_RT=`"`r`nset /p VI_RT=<`"$ptr`"`r`nif not exist `"%VI_RT%\bin\java.exe`" (`r`n  echo %~n0: the runtime '$($b.runtime)' is not installed 1>&2`r`n  exit /b 1`r`n)`r`n`"%VI_RT%\bin\java.exe`"$jvm -jar `"%~dp0$jarName`" %*`r`n"
    }
    return "@echo off`r`njava$jvm -jar `"%~dp0$jarName`" %*`r`n"
}

# javaw.exe for a jar's windowed start (shortcuts, file associations): its runtime install's, or the one
# on PATH / JAVA_HOME. $null means start it through the .cmd launcher instead.
function ViJavaw($b) {
    if (-not $b.runtime) { return (ViFindJava 'javaw') }
    $rt = ViReadRecord $b.runtime
    if ($rt) {
        $cand = Join-Path $rt.installDir 'bin\javaw.exe'
        if (Test-Path -LiteralPath $cand) { return $cand }
    }
    return $null
}

function ViShortcut([string]$lnk, [string]$target, [string]$arguments, [string]$workDir, [string]$desc, [string]$icon) {
    ViEnsureDir (Split-Path $lnk -Parent)
    $s = (New-Object -ComObject WScript.Shell).CreateShortcut($lnk)
    $s.TargetPath = $target
    if ($arguments) { $s.Arguments = $arguments }
    if ($workDir) { $s.WorkingDirectory = $workDir }
    if ($desc) { $s.Description = $desc }
    if ($icon) { $s.IconLocation = "$icon,0" }
    $s.Save()
}

# ---- window ----------------------------------------------------------------------------
# Everything runs on this one thread: the window's event handlers only set $ViUi.Action, the install code
# reads it, and Application.DoEvents (from ViUiLog, ViDownload and ViUiWait) keeps the window responsive.
# The handlers are closures, so they touch $ui and .NET objects only, never the Vi* functions.

function ViWantsWindow([bool]$quiet) {
    if ($quiet -or ($env:INSTALL_QUIET -and $env:INSTALL_QUIET -ne '0') -or $env:CI) { return $false }
    if (-not [Environment]::UserInteractive) { return $false }
    if (@([Environment]::GetCommandLineArgs() | Where-Object { $_ -match '^[-/]noni' }).Count -gt 0) { return $false }
    try { if ([Console]::IsOutputRedirected) { return $false } } catch { }
    try { Add-Type -AssemblyName System.Windows.Forms, System.Drawing; return $true } catch { return $false }
}

function ViUiOpen {
    try {
        if (-not ('ViWin.ViDpi' -as [type])) {
            Add-Type -Namespace ViWin -Name ViDpi -MemberDefinition '[DllImport("user32.dll")] public static extern bool SetProcessDPIAware();'
        }
        [void][ViWin.ViDpi]::SetProcessDPIAware()
    } catch { }
    [Windows.Forms.Application]::EnableVisualStyles()
    $ui = @{ Action = $null; Closed = $false; Phase = 'busy'; Leaf = $null }

    $f = New-Object Windows.Forms.Form
    $f.SuspendLayout()
    $f.AutoScaleDimensions = New-Object Drawing.SizeF(96, 96)
    $f.AutoScaleMode = [Windows.Forms.AutoScaleMode]::Dpi
    $f.Font = New-Object Drawing.Font('Segoe UI', 9)
    $f.Text = "$($InstallerCfg.name) Setup"
    $f.FormBorderStyle = 'FixedDialog'
    $f.MaximizeBox = $false
    $f.StartPosition = 'CenterScreen'
    $f.ClientSize = New-Object Drawing.Size(580, 420)

    # header: title and one line under it
    $head = New-Object Windows.Forms.Panel
    $head.Dock = 'Top'; $head.Height = 68; $head.BackColor = [Drawing.SystemColors]::Window
    $title = New-Object Windows.Forms.Label
    $title.AutoSize = $true; $title.Location = New-Object Drawing.Point(18, 12)
    $title.Font = New-Object Drawing.Font('Segoe UI Semibold', 12)
    $sub = New-Object Windows.Forms.Label
    $sub.AutoSize = $false; $sub.Location = New-Object Drawing.Point(19, 40); $sub.Size = New-Object Drawing.Size(545, 20)
    $sub.AutoEllipsis = $true; $sub.ForeColor = [Drawing.SystemColors]::GrayText
    $head.Controls.AddRange(@($title, $sub))
    $rule = New-Object Windows.Forms.Panel
    $rule.Dock = 'Top'; $rule.Height = 1; $rule.BackColor = [Drawing.SystemColors]::ControlDark

    # buttons: the primary one left of the secondary one, a link on the left
    $bar = New-Object Windows.Forms.Panel
    $bar.Dock = 'Bottom'; $bar.Height = 50
    $flow = New-Object Windows.Forms.FlowLayoutPanel
    $flow.Dock = 'Right'; $flow.FlowDirection = 'RightToLeft'; $flow.AutoSize = $true; $flow.WrapContents = $false
    $flow.Padding = New-Object Windows.Forms.Padding(0, 10, 10, 0)
    $b2 = New-Object Windows.Forms.Button
    $b1 = New-Object Windows.Forms.Button
    foreach ($b in $b2, $b1) {
        $b.AutoSize = $true; $b.MinimumSize = New-Object Drawing.Size(92, 28); $b.Margin = New-Object Windows.Forms.Padding(6, 0, 0, 0)
    }
    $flow.Controls.AddRange(@($b2, $b1))
    $link = New-Object Windows.Forms.LinkLabel
    $link.AutoSize = $true; $link.Location = New-Object Drawing.Point(18, 17); $link.Visible = $false
    $bar.Controls.AddRange(@($flow, $link))

    $body = New-Object Windows.Forms.Panel
    $body.Dock = 'Fill'; $body.Padding = New-Object Windows.Forms.Padding(18, 14, 18, 6)

    # options page
    $opts = New-Object Windows.Forms.Panel
    $opts.Dock = 'Fill'
    $dirLabel = New-Object Windows.Forms.Label
    $dirLabel.Text = 'Install to'; $dirLabel.AutoSize = $true; $dirLabel.Location = New-Object Drawing.Point(0, 2)
    $dir = New-Object Windows.Forms.TextBox
    $dir.Location = New-Object Drawing.Point(0, 24); $dir.Size = New-Object Drawing.Size(446, 25)
    $browse = New-Object Windows.Forms.Button
    $browse.Text = 'Browse...'; $browse.Location = New-Object Drawing.Point(452, 23); $browse.Size = New-Object Drawing.Size(92, 27)
    $cbs = @()
    $y = 70
    foreach ($i in 0..2) {
        $cb = New-Object Windows.Forms.CheckBox
        $cb.AutoSize = $true; $cb.Location = New-Object Drawing.Point(2, $y); $cb.Visible = $false
        $cbs += $cb; $y += 28
    }
    $note = New-Object Windows.Forms.Label
    $note.Dock = 'Bottom'; $note.Height = 40; $note.ForeColor = [Drawing.SystemColors]::GrayText
    $note.Text = 'Each download is checked against its SHA-256 before anything is written to the folder. Everything goes into your user account; no administrator rights are needed.'
    $opts.Controls.AddRange(@($dirLabel, $dir, $browse, $note) + $cbs)

    # progress page: status, bar, log
    $prog = New-Object Windows.Forms.Panel
    $prog.Dock = 'Fill'; $prog.Visible = $false
    $log = New-Object Windows.Forms.TextBox
    $log.Dock = 'Fill'; $log.Multiline = $true; $log.ReadOnly = $true; $log.ScrollBars = 'Vertical'
    $log.Font = New-Object Drawing.Font('Consolas', 9); $log.BackColor = [Drawing.SystemColors]::Window
    $gap = New-Object Windows.Forms.Panel
    $gap.Dock = 'Top'; $gap.Height = 10
    $pbar = New-Object Windows.Forms.ProgressBar
    $pbar.Dock = 'Top'; $pbar.Height = 18; $pbar.MarqueeAnimationSpeed = 30; $pbar.Style = 'Marquee'
    $status = New-Object Windows.Forms.Label
    $status.Dock = 'Top'; $status.Height = 38; $status.AutoEllipsis = $true
    # docking runs from the last control added to the first, so they are added bottom-up
    $prog.Controls.AddRange(@($log, $gap, $pbar, $status))

    $body.Controls.AddRange(@($opts, $prog))
    $f.Controls.AddRange(@($body, $rule, $head, $bar))
    $f.AcceptButton = $b1

    $ui.Form = $f; $ui.Title = $title; $ui.Sub = $sub; $ui.B1 = $b1; $ui.B2 = $b2; $ui.Link = $link
    $ui.Options = $opts; $ui.Dir = $dir; $ui.Checks = $cbs; $ui.Progress = $prog
    $ui.Status = $status; $ui.Bar = $pbar; $ui.Log = $log

    $b1.add_Click({ $ui.Action = 'primary' }.GetNewClosure())
    $b2.add_Click({ $ui.Action = 'secondary' }.GetNewClosure())
    $link.add_LinkClicked({ $ui.Action = 'link' }.GetNewClosure())
    $browse.add_Click({
        $d = New-Object Windows.Forms.FolderBrowserDialog
        $d.Description = 'Choose the folder to install into.'
        $start = $ui.Dir.Text.Trim()
        while ($start -and -not (Test-Path -LiteralPath $start -PathType Container)) { $start = Split-Path $start -Parent }
        if ($start) { $d.SelectedPath = $start }
        if ($d.ShowDialog($ui.Form) -eq [Windows.Forms.DialogResult]::OK) {
            $p = $d.SelectedPath.TrimEnd('\')
            # a folder of its own inside the one chosen, as installers usually do
            if ($ui.Leaf -and (Split-Path $p -Leaf) -ne $ui.Leaf) { $p = Join-Path $p $ui.Leaf }
            $ui.Dir.Text = $p
        }
        $d.Dispose()
    }.GetNewClosure())
    # closing is cancelling while downloading, and is refused while files are being placed
    $f.add_FormClosing({
        param($s, $e)
        if ($ui.Phase -eq 'busy') { $e.Cancel = $true }
        elseif ($ui.Phase -eq 'download') { $e.Cancel = $true; $ui.Action = 'secondary' }
    }.GetNewClosure())
    $f.add_FormClosed({ $ui.Closed = $true; if (-not $ui.Action) { $ui.Action = 'close' } }.GetNewClosure())

    ViUiPage $ui 'progress'
    $title.Text = "Install $($InstallerCfg.name)"
    $sub.Text = $InstallerCfg.description
    $b1.Visible = $false
    $b2.Text = 'Cancel'; $b2.Enabled = $false
    $f.ResumeLayout($false)
    $f.TopMost = $true
    $f.Show()
    $f.Activate()
    $f.TopMost = $false
    [Windows.Forms.Application]::DoEvents()
    $ui
}

function ViUiPage($ui, [string]$page) {
    $ui.Options.Visible = $page -eq 'options'
    $ui.Progress.Visible = $page -eq 'progress'
}

# 'busy' (closing refused), 'download' (closing or Cancel cancels), 'options' or 'done' (closing closes)
function ViUiPhase([string]$phase) {
    if (-not $ViUi -or $ViUi.Closed) { return }
    $ViUi.Phase = $phase
    $ViUi.Action = $null
    if ($phase -eq 'busy' -or $phase -eq 'download') {
        $ViUi.B1.Visible = $false
        $ViUi.B2.Text = 'Cancel'
        $ViUi.B2.Enabled = $phase -eq 'download'
    }
}

# Waits for a button, the link or the window being closed; returns 'primary', 'secondary', 'link' or 'close'.
function ViUiWait {
    $ViUi.Action = $null
    while (-not $ViUi.Action -and -not $ViUi.Closed) { [Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 25 }
    if ($ViUi.Action) { $ViUi.Action } else { 'close' }
}

function ViUiAsk([string]$text) {
    $r = [Windows.Forms.MessageBox]::Show($ViUi.Form, $text, $ViUi.Form.Text, [Windows.Forms.MessageBoxButtons]::YesNo,
        [Windows.Forms.MessageBoxIcon]::Warning, [Windows.Forms.MessageBoxDefaultButton]::Button2)
    $r -eq [Windows.Forms.DialogResult]::Yes
}

function ViCommandName($b) {
    $p = if ($b.kind -eq 'jar') { $b.launcher } else { $b.installPath }
    [IO.Path]::GetFileNameWithoutExtension($p)
}

# The options page, filled from what this install would do. Returns the choices, or $null when cancelled.
function ViUiOptions([string]$version, $old, [string]$installDir, [string]$defaultDir, [bool]$noShortcuts, [bool]$noPath, [bool]$noAssoc, $bins) {
    $ui = $ViUi
    $appName = $InstallerCfg.name
    $verb = 'Install'
    $ui.Sub.Text = "Version $version from $($InstallerCfg.publisher)"
    if ($old) {
        $c = ViCompare $version $old.version
        if ($c -eq 0) { $verb = 'Reinstall'; $ui.Sub.Text = "Version $version is installed already. Reinstall it, or change its options." }
        elseif ($c -gt 0) { $verb = 'Update'; $ui.Sub.Text = "Updates version $($old.version) to $version" }
        else { $ui.Sub.Text = "Replaces version $($old.version) with the older $version" }
    }
    $ui.Title.Text = "$verb $appName"
    $ui.Dir.Text = $installDir
    $ui.Leaf = Split-Path $defaultDir -Leaf

    $desk = @($bins | Where-Object { $_.shortcuts -and $_.shortcuts.desktop }).Count -gt 0
    $menu = @($bins | Where-Object { $_.shortcuts -and $_.shortcuts.startMenu }).Count -gt 0
    $cmds = @($bins | Where-Object { $_.addToPath } | ForEach-Object { ViCommandName $_ } | Select-Object -Unique)
    $exts = @($bins | ForEach-Object { @($_.fileAssociations) } | Where-Object { $_ } | ForEach-Object { $_.extension } | Select-Object -Unique)
    $rows = @()
    if ($desk -or $menu) {
        $where = if ($desk -and $menu) { 'on the desktop and in the Start menu' } elseif ($desk) { 'on the desktop' } else { 'in the Start menu' }
        $rows += [pscustomobject]@{ Key = 'shortcuts'; Text = "Create shortcuts $where"; Skip = $noShortcuts }
    }
    if ($cmds.Count -gt 0) {
        $rows += [pscustomobject]@{ Key = 'path'; Text = "Add to PATH, so $($cmds -join ', ') can be run from a terminal"; Skip = $noPath }
    }
    if ($exts.Count -gt 0) {
        $rows += [pscustomobject]@{ Key = 'assoc'; Text = "Open $($exts -join ', ') files with $appName"; Skip = $noAssoc }
    }
    for ($i = 0; $i -lt $ui.Checks.Count; $i++) {
        $cb = $ui.Checks[$i]
        # (Visible reads false while the page is hidden, so the Tag says which boxes are in use)
        $cb.Visible = $i -lt $rows.Count
        $cb.Tag = $null
        if ($i -lt $rows.Count) { $cb.Text = $rows[$i].Text; $cb.Checked = -not $rows[$i].Skip; $cb.Tag = $rows[$i].Key }
    }

    ViUiPage $ui 'options'
    ViUiPhase 'options'
    $ui.B1.Text = $verb; $ui.B1.Visible = $true; $ui.B1.Enabled = $true
    $ui.B2.Text = 'Cancel'; $ui.B2.Enabled = $true
    $ui.B1.Focus() | Out-Null
    while ($true) {
        if ((ViUiWait) -ne 'primary') { return $null }
        $d = ViExpand $ui.Dir.Text.Trim()
        $ok = $false
        try { $ok = [IO.Path]::IsPathRooted($d) -and $d -match '^([a-zA-Z]:\\|\\\\)' -and [IO.Path]::GetFullPath($d) } catch { }
        if ($ok) { break }
        [void][Windows.Forms.MessageBox]::Show($ui.Form, "Choose a full folder path, such as $installDir.", $ui.Form.Text,
            [Windows.Forms.MessageBoxButtons]::OK, [Windows.Forms.MessageBoxIcon]::Warning)
    }
    $pick = [ordered]@{ Dir = ([IO.Path]::GetFullPath($d)).TrimEnd('\'); NoShortcuts = $noShortcuts; NoPath = $noPath; NoAssociations = $noAssoc }
    foreach ($cb in $ui.Checks) {
        switch ($cb.Tag) {
            'shortcuts' { $pick.NoShortcuts = -not $cb.Checked }
            'path' { $pick.NoPath = -not $cb.Checked }
            'assoc' { $pick.NoAssociations = -not $cb.Checked }
        }
    }
    ViUiPage $ui 'progress'
    $ui.Title.Text = "Installing $appName"
    $ui.Sub.Text = "Version $version into $($pick.Dir)"
    [pscustomobject]$pick
}

# The last page: what happened, and what can be done next. Returns when the window is closed.
function ViUiFinish([bool]$ok, [string]$err) {
    if (-not $ViUi -or $ViUi.Closed) { return }
    $ui = $ViUi
    $appName = $InstallerCfg.name
    try {
        if ($ViState.Cancelled) { return }
        ViUiPage $ui 'progress'
        ViUiPhase 'done'
        $ui.B2.Text = 'Close'; $ui.B2.Enabled = $true
        $ui.Form.AcceptButton = $ui.B2
        if ($ok) {
            $ui.Title.Text = "$appName is installed"
            ViUiBar 100
            $ui.Status.Text = "$appName $($ViState.Version) is installed in $($ViState.Dir)."
            if ($ViState.Launch) {
                $ui.B1.Text = "Start $($ViState.LaunchLabel)"; $ui.B1.Visible = $true
                $ui.Form.AcceptButton = $ui.B1
                $ui.B1.Focus() | Out-Null
            }
        } else {
            $ui.Title.Text = "$appName was not installed"
            ViUiBar 0
            $ui.Status.ForeColor = [Drawing.Color]::FromArgb(176, 0, 32)
            $ui.Status.Text = $err
            if ($ViState.Report) { $ui.B1.Text = 'Open report'; $ui.B1.Visible = $true }
            if ($InstallerCfg.issuesUrl) { $ui.Link.Text = 'Report the problem'; $ui.Link.Visible = $true }
        }
        while ($true) {
            switch (ViUiWait) {
                'primary' {
                    if ($ok) {
                        try { Start-Process -FilePath $ViState.Launch } catch { ViWarn "Could not start $($ViState.LaunchLabel): $($_.Exception.Message)" }
                        return
                    }
                    try { Start-Process -FilePath $ViState.Report } catch { }
                }
                'link' { try { Start-Process -FilePath $InstallerCfg.issuesUrl } catch { } }
                default { return }
            }
        }
    } finally {
        if (-not $ui.Closed) { $ui.Phase = 'done'; $ui.Form.Close() }
        $ui.Form.Dispose()
    }
}

# Invoke-WebRequest -OutFile, or with a window a chunked download that shows its progress, keeps the
# window responsive and stops when Cancel is pressed. Without a window of its own, the window is the one a
# suite installer running this one quietly leaves in $ViHostUi, if any (with the same Status, Bar and Action).
function ViDownload([string]$url, [string]$out, [string]$label) {
    $ui = $ViUi
    if (-not $ui -and $ViHostUi -and -not $ViHostUi.Closed) { $ui = $ViHostUi }
    if (-not $ui -or $ui.Closed) { Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $out; return }
    $ui.Status.Text = "Downloading $label"
    [Windows.Forms.Application]::DoEvents()
    $req = [Net.WebRequest]::Create($url)
    $req.UserAgent = 'vexelray-installer'
    $resp = $req.GetResponse()
    try {
        $total = $resp.ContentLength
        $in = $resp.GetResponseStream()
        $fs = [IO.File]::Create($out)
        try {
            $buf = New-Object byte[] 262144
            $done = 0L; $shown = -1
            ViUiBar $(if ($total -gt 0) { 0 } else { -1 }) $ui
            while (($n = $in.Read($buf, 0, $buf.Length)) -gt 0) {
                $fs.Write($buf, 0, $n)
                $done += $n
                if ($total -gt 0) {
                    $pct = [int](100 * $done / $total)
                    if ($pct -ne $shown) {
                        $shown = $pct
                        ViUiBar $pct $ui
                        $ui.Status.Text = "Downloading {0} ({1:N1} of {2:N1} MB)" -f $label, ($done / 1MB), ($total / 1MB)
                    }
                }
                [Windows.Forms.Application]::DoEvents()
                if ($ui.Action -eq 'secondary') { $ViState.Cancelled = $true; throw 'Cancelled. Nothing was installed.' }
            }
        } finally { $fs.Dispose(); $in.Dispose() }
    } finally { $resp.Close() }
}

# ---- transaction -----------------------------------------------------------------------
# Every file the install writes goes through ViTxPut. The file it replaces is first renamed into a backup
# folder (a rename, so even a running .exe can be replaced), and a line in <registryDir>\<id>.journal says
# what is about to happen before it does. A failure plays the journal backwards; a run that was killed is
# rolled back by the next one, or finished if it got as far as its commit line. Files in the install folder
# are backed up inside it, so their renames stay on one volume.

function ViTxBegin([string]$id, [string]$installDir, [string]$tmp) {
    $regDir = ViRegistryDir
    ViEnsureDir $regDir
    $tag = [guid]::NewGuid().ToString('N').Substring(0, 8)
    $tx = [pscustomobject]@{
        Journal = Join-Path $regDir "$id.journal"
        InstallDir = $installDir
        Backup = Join-Path $installDir ".vi-backup-$tag"
        OtherBackup = Join-Path (Split-Path $regDir -Parent) "backup\$id-$tag"
        Tmp = $tmp
        Puts = 0
        N = 0
    }
    ViTxLog $tx @{ op = 'begin'; installDir = $installDir; backup = $tx.Backup; otherBackup = $tx.OtherBackup; at = (Get-Date).ToString('o') }
    $tx
}

function ViTxLog($tx, $entry) {
    [IO.File]::AppendAllText($tx.Journal, (($entry | ConvertTo-Json -Compress -Depth 6) + "`n"), (New-Object Text.UTF8Encoding $false))
}

# Creates a folder and any missing parents, journalling each so a rollback removes them again (when empty).
function ViTxDir($tx, [string]$dir) {
    if (-not $dir -or (Test-Path -LiteralPath $dir)) { return }
    $missing = @()
    $d = $dir
    while ($d -and -not (Test-Path -LiteralPath $d)) { $missing = @($d) + $missing; $d = Split-Path $d -Parent }
    foreach ($m in $missing) {
        ViTxLog $tx @{ op = 'dir'; d = $m }
        New-Item -ItemType Directory -Path $m | Out-Null
    }
}

function ViTxBackupPath($tx, [string]$path) {
    $root = $tx.InstallDir.TrimEnd('\') + '\'
    if ($path.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) { return Join-Path $tx.Backup $path.Substring($root.Length) }
    $tx.N++
    Join-Path $tx.OtherBackup ("{0}-{1}" -f $tx.N, (Split-Path $path -Leaf))
}

# Moves an existing file into the backup. A file held open (a jar a running JVM has, say) is offered to be
# closed (ViCloseRunning); if it cannot be, the install fails and is rolled back.
function ViTxAside($tx, [string]$path) {
    $b = ViTxBackupPath $tx $path
    ViTxLog $tx @{ op = 'put'; t = $path; b = $b }
    ViEnsureDir (Split-Path $b -Parent)
    for ($try = 0; ; $try++) {
        try { [IO.File]::Move($path, $b); break }
        catch {
            $why = if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message }
            if ($try -ge 1 -or -not (ViCloseRunning $tx.InstallDir $path)) {
                throw "Could not replace ${path}: $why Close $($InstallerCfg.name) and run the install again, or set INSTALL_CLOSE_APPS=1 to have it closed."
            }
        }
    }
}

# Puts $src (a file in the temp folder) at $dst, backing up what was there.
function ViTxPut($tx, [string]$src, [string]$dst) {
    ViTxDir $tx (Split-Path $dst -Parent)
    if (Test-Path -LiteralPath $dst) { ViTxAside $tx $dst } else { ViTxLog $tx @{ op = 'put'; t = $dst; b = $null } }
    Move-Item -Force -LiteralPath $src -Destination $dst
    ViTxFault $tx
}

# Writes a small file through ViTxPut, or leaves it alone when it already says exactly that.
function ViTxPutText($tx, [string]$dst, [string]$text) {
    if ((Test-Path -LiteralPath $dst) -and ([IO.File]::ReadAllText($dst) -ceq $text)) { return }
    $t = Join-Path $tx.Tmp ("t-" + [guid]::NewGuid().ToString('N'))
    ViWriteText $t $text
    ViTxPut $tx $t $dst
}

# For tests only: INSTALL_TEST_FAULT=throw:<n> or exit:<n> fails, or kills the process, after the n-th file
# is put in place; throw:commit and exit:commit do it just before the commit.
function ViTxFault($tx, [string]$point = 'put') {
    if (-not $env:INSTALL_TEST_FAULT) { return }
    $how, $at = $env:INSTALL_TEST_FAULT -split ':'
    if ($point -eq 'put') { $tx.Puts++; if ($at -ne [string]$tx.Puts) { return } }
    elseif ($at -ne $point) { return }
    if ($how -eq 'exit') { [Environment]::Exit(9) }
    throw "Test fault at $($env:INSTALL_TEST_FAULT)."
}

function ViTxCommit($tx) {
    ViTxFault $tx 'commit'
    ViTxLog $tx @{ op = 'commit' }
    ViTxFinish $tx.Journal
}

function ViTxRead([string]$journal) {
    @(Get-Content -LiteralPath $journal -ErrorAction SilentlyContinue | Where-Object { $_.Trim() } | ForEach-Object { try { $_ | ConvertFrom-Json } catch { } })
}

# After the commit: the backups go (a running .exe in one may refuse until it exits; the next run retries),
# then the journal.
function ViTxFinish([string]$journal) {
    $begin = ViTxRead $journal | Where-Object { $_.op -eq 'begin' } | Select-Object -First 1
    $left = $false
    foreach ($b in @($begin.backup, $begin.otherBackup)) {
        if ($b -and (Test-Path -LiteralPath $b)) {
            Remove-Item -Recurse -Force -LiteralPath $b -ErrorAction SilentlyContinue
            if (Test-Path -LiteralPath $b) { $left = $true }
        }
    }
    if (-not $left) { Remove-Item -Force -LiteralPath $journal -ErrorAction SilentlyContinue }
}

# Plays a journal backwards: replaced files come back, new files and folders go, PATH entries and file
# types it added are taken out again. Returns $false when something could not be put back (the journal
# then stays, for the next run to try again).
function ViTxRollback([string]$journal) {
    $lines = ViTxRead $journal
    $ok = $true
    for ($i = $lines.Count - 1; $i -ge 0; $i--) {
        $e = $lines[$i]
        try {
            switch ($e.op) {
                'put' {
                    if ($e.b -and (Test-Path -LiteralPath $e.b)) {
                        if (Test-Path -LiteralPath $e.t) { Remove-Item -Force -LiteralPath $e.t }
                        ViEnsureDir (Split-Path $e.t -Parent)
                        [IO.File]::Move($e.b, $e.t)
                    } elseif (-not $e.b -and (Test-Path -LiteralPath $e.t)) { Remove-Item -Force -LiteralPath $e.t }
                }
                'dir' { if ((Test-Path -LiteralPath $e.d) -and -not (Get-ChildItem -LiteralPath $e.d -Force)) { Remove-Item -Force -LiteralPath $e.d } }
                'path' { ViPathRemove $e.dir }
                'assoc' { ViAssocRemove $e.a }
            }
        } catch {
            $ok = $false
            ViWarn "Could not undo $($e.op) $($e.t)$($e.d)$($e.dir): $($_.Exception.Message)"
        }
    }
    if (@($lines | Where-Object { $_.op -eq 'assoc' }).Count -gt 0) { ViNotifyAssoc }
    if ($ok) {
        $begin = $lines | Where-Object { $_.op -eq 'begin' } | Select-Object -First 1
        foreach ($b in @($begin.backup, $begin.otherBackup)) {
            if ($b -and (Test-Path -LiteralPath $b)) { Remove-Item -Recurse -Force -LiteralPath $b -ErrorAction SilentlyContinue }
        }
        Remove-Item -Force -LiteralPath $journal -ErrorAction SilentlyContinue
    }
    $ok
}

# A journal left by an earlier run: finished if it committed, rolled back if not.
function ViTxRecover([string]$journal) {
    if (-not (Test-Path -LiteralPath $journal)) { return }
    $lines = ViTxRead $journal
    if (@($lines | Where-Object { $_.op -eq 'commit' }).Count -gt 0) { ViTxFinish $journal; return }
    ViWarn "The last install of $($InstallerCfg.name) did not finish; putting back what it had replaced."
    if (-not (ViTxRollback $journal)) { throw "The unfinished install could not be undone completely (see the warnings above). Close $($InstallerCfg.name) and try again." }
    ViInfo "Put back."
}

# Processes started from the install folder (by path, or with it on their command line, as a JVM running a
# jar has), leaving out this one and its parents (update.cmd runs from there). With INSTALL_CLOSE_APPS=1, or
# when the window asks and the answer is yes, they are closed: politely, then forcibly after ten seconds.
function ViRunningFrom([string]$dir) {
    $root = $dir.TrimEnd('\') + '\'
    $all = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue)
    $byId = @{}
    foreach ($p in $all) { $byId[[int]$p.ProcessId] = $p }
    $mine = @{}
    $c = [int]$PID
    while ($c -and $byId.ContainsKey($c) -and -not $mine.ContainsKey($c)) { $mine[$c] = $true; $c = [int]$byId[$c].ParentProcessId }
    @($all | Where-Object {
        -not $mine.ContainsKey([int]$_.ProcessId) -and (
            ($_.ExecutablePath -and $_.ExecutablePath.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) -or
            ($_.CommandLine -and $_.CommandLine.IndexOf($root, [StringComparison]::OrdinalIgnoreCase) -ge 0))
    })
}

function ViCloseRunning([string]$dir, [string]$path) {
    $procs = ViRunningFrom $dir
    if ($procs.Count -eq 0) { return $false }
    $names = ($procs | ForEach-Object { "$($_.Name) (process $($_.ProcessId))" }) -join ', '
    $yes = $env:INSTALL_CLOSE_APPS -and $env:INSTALL_CLOSE_APPS -ne '0'
    if (-not $yes -and $ViUi -and -not $ViUi.Closed) {
        $yes = ViUiAsk "$(Split-Path $path -Leaf) is in use by $names, so it cannot be replaced.`n`nClose it and continue?"
    }
    if (-not $yes) { ViWarn "$(Split-Path $path -Leaf) is in use by $names."; return $false }
    ViInfo "Closing $names"
    $live = @($procs | ForEach-Object { Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue } | Where-Object { $_ })
    foreach ($p in $live) { try { [void]$p.CloseMainWindow() } catch { } }
    $until = (Get-Date).AddSeconds(10)
    while ((Get-Date) -lt $until -and @($live | Where-Object { -not $_.HasExited }).Count -gt 0) {
        if ($ViUi -and -not $ViUi.Closed) { [Windows.Forms.Application]::DoEvents() }
        Start-Sleep -Milliseconds 200
    }
    foreach ($p in $live) { if (-not $p.HasExited) { try { $p.Kill(); [void]$p.WaitForExit(5000) } catch { } } }
    Start-Sleep -Milliseconds 300
    return $true
}

# One install of an application at a time: the lock is a file held open until the run ends.
function ViLock([string]$id) {
    $regDir = ViRegistryDir
    ViEnsureDir $regDir
    try { return [IO.File]::Open((Join-Path $regDir "$id.lock"), 'OpenOrCreate', 'ReadWrite', 'None') }
    catch { throw "Another install, update or removal of $($InstallerCfg.name) is running. Let it finish, then try again." }
}

# ---- install ---------------------------------------------------------------------------

function ViOptOut([bool]$switch, [string]$envValue, $stored) {
    if ($switch) { return $true }
    if ($envValue -eq '0') { return $false }
    if ($envValue) { return $true }
    [bool]$stored
}

function ViInvokeInstall {
    param([string]$Version, [string]$Dir, [switch]$NoShortcuts, [switch]$NoPath, [switch]$NoAssociations, [switch]$Force, [switch]$SkipChecks)
    $ErrorActionPreference = 'Stop'
    $ProgressPreference = 'SilentlyContinue'
    $id = $InstallerCfg.id
    $appName = $InstallerCfg.name

    if ($env:OS -ne 'Windows_NT') { throw "${appName}: this installer supports Windows only for now." }
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

    ViStep "Fetching install manifest"
    $manifest = (ViGet $InstallerCfg.manifestUrl) | ConvertFrom-Json
    if ($manifest.id -ne $id) { throw "Manifest is for '$($manifest.id)', expected '$id'." }
    $want = if ($Version) { $Version -replace '^[vV]', '' } else { $manifest.latest }
    $entry = @($manifest.versions) | Where-Object { $_.version -eq $want } | Select-Object -First 1
    if (-not $entry) {
        $avail = (@($manifest.versions) | ForEach-Object { $_.version }) -join ', '
        throw "Version '$want' is not in the manifest. Available: $avail"
    }
    $plat = $entry.platforms.windows
    if (-not $plat) { throw "$appName $want has no Windows build." }

    foreach ($rq in @($plat.requires.installs)) {
        if (-not $rq.id) { continue }
        $dep = ViReadRecord $rq.id
        if (-not $dep) { throw "$appName needs '$($rq.id)' to be installed first. Install it, then run this again." }
        if ($rq.min -and (ViCompare $dep.version $rq.min) -lt 0) {
            throw "$appName needs $($rq.id) $($rq.min) or newer, but $($dep.version) is installed. Update it first."
        }
    }

    $regDir = ViRegistryDir
    $recPath = Join-Path $regDir "$id.json"
    $ViState.Lock = ViLock $id
    ViTxRecover (Join-Path $regDir "$id.journal")
    $old = $null
    if (Test-Path -LiteralPath $recPath) {
        try { $old = Get-Content -Raw -LiteralPath $recPath | ConvertFrom-Json } catch { }
    }
    if ($Dir) { $installDir = (ViExpand $Dir).TrimEnd('\') }
    elseif ($old) { $installDir = $old.installDir }
    else { $installDir = (ViExpand $plat.installDir).TrimEnd('\') }

    # opt-outs: a switch or INSTALL_NO_*=1 skips, INSTALL_NO_*=0 opts back in, otherwise the last install's choice stands
    $skipShortcuts = ViOptOut $NoShortcuts $env:INSTALL_NO_SHORTCUTS $old.options.noShortcuts
    $skipPath = ViOptOut $NoPath $env:INSTALL_NO_PATH $old.options.noPath
    $skipAssoc = ViOptOut $NoAssociations $env:INSTALL_NO_ASSOCIATIONS $old.options.noAssociations
    $bins = @($plat.binaries)

    # with a window those are the defaults it offers; pressing Install (or Reinstall) is the go-ahead
    if ($ViUi) {
        $pick = ViUiOptions $entry.version $old $installDir (ViExpand $plat.installDir).TrimEnd('\') $skipShortcuts $skipPath $skipAssoc $bins
        if (-not $pick) { $ViState.Cancelled = $true; Write-Host 'Cancelled. Nothing was installed.'; return $false }
        $installDir = $pick.Dir
        $skipShortcuts = $pick.NoShortcuts; $skipPath = $pick.NoPath; $skipAssoc = $pick.NoAssociations
        $Force = $true
        ViUiPhase 'download'
    }
    $ViState.Version = $entry.version
    $ViState.Dir = $installDir

    if ($old -and $old.version -eq $entry.version -and $old.installDir -eq $installDir -and -not $Force) {
        Write-Host "$appName $($entry.version) is already installed in $installDir. Set INSTALL_FORCE=1 to reinstall."
        return $true
    }

    $jars = @($bins | Where-Object { $_.kind -eq 'jar' -and -not $_.runtime })
    if ($jars.Count -gt 0) {
        $java = ViFindJava 'java'
        $need = [int]$plat.requires.java
        if (-not $java) {
            ViWarn "Java was not found. $appName needs a Java runtime$(if ($need) { " (version $need or newer)" }) on PATH or JAVA_HOME to start."
        } elseif ($need -gt 0) {
            $major = ViJavaMajor $java
            if ($major -gt 0 -and $major -lt $need) { ViWarn "Java $major found at $java, but $appName needs Java $need or newer." }
        }
    }

    $tmp = Join-Path ([IO.Path]::GetTempPath()) ("install-" + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $tmp | Out-Null
    try {
        # 1. download + verify everything before touching the install directory; the tools come first, as
        # diagnose.ps1 checks the system requirements before anything large is downloaded
        $tools = @()
        foreach ($tn in 'uninstall.ps1', 'update.ps1', 'diagnose.ps1') {
            $t = $manifest.tools.$tn
            if (-not $t) { continue }
            $dl = Join-Path $tmp $tn
            ViDownload $t.url $dl $tn
            if ((ViSha $dl) -ne $t.sha256) { throw "Checksum mismatch for $tn downloaded from $($t.url). Nothing was installed." }
            $tools += [pscustomobject]@{ Name = $tn; Temp = $dl; Sha = $t.sha256 }
            if ($tn -eq 'diagnose.ps1') { $ViState.DiagText = [IO.File]::ReadAllText($dl) }
        }
        if ($ViState.DiagText -and $plat.requires.system) {
            ViStep "Checking system requirements"
            $chk = $null
            try {
                $chk = & ([scriptblock]::Create($ViState.DiagText)) -Check -Requires ($plat.requires.system | ConvertTo-Json -Compress -Depth 5) `
                    -InstallDir $installDir -Installing $entry.version | Select-Object -Last 1
            } catch { ViWarn "The system check could not run: $($_.Exception.Message)" }
            if ($chk) {
                foreach ($c in @($chk.unknown)) { ViWarn "Could not check: $($c.check) ($($c.found))" }
                foreach ($c in @($chk.failed)) { ViSay "    Not met: $($c.check)`n             found: $($c.found)" Red }
                $unmet = (@($chk.failed) | ForEach-Object { "- $($_.check) (found: $($_.found))" }) -join "`n"
                if ($chk.ok) { ViInfo "Met" }
                elseif ($SkipChecks) { ViWarn "Installing anyway, as INSTALL_SKIP_CHECKS is set. $appName may not start or may misbehave." }
                elseif ($ViUi -and (ViUiAsk "This computer does not meet the system requirements of ${appName}:`n`n$unmet`n`n$appName may not start, or may misbehave. Install it anyway?")) {
                    ViWarn "Installing anyway, as asked. $appName may not start or may misbehave."
                }
                else {
                    $ViState.Report = $chk.report
                    throw "This computer does not meet the system requirements of $appName. Nothing was installed. Set INSTALL_SKIP_CHECKS=1 to install anyway."
                }
            }
        }

        ViStep "Downloading $appName $($entry.version)"
        $staged = @()
        foreach ($b in $bins) {
            $ic = $null
            if ($b.icon) {
                $itarget = ViExpand $b.icon.installPath.Replace('{installDir}', $installDir)
                $itemp = $null
                if (-not ((Test-Path -LiteralPath $itarget) -and ((ViSha $itarget) -eq $b.icon.sha256))) {
                    ViInfo "$($b.icon.file)"
                    $itemp = Join-Path $tmp $b.icon.file
                    ViDownload $b.icon.url $itemp $b.icon.file
                    if ((ViSha $itemp) -ne $b.icon.sha256) { throw "Checksum mismatch for $($b.icon.file) downloaded from $($b.icon.url). Nothing was installed." }
                }
                $ic = [pscustomobject]@{ Target = $itarget; Temp = $itemp; Meta = $b.icon }
            }
            $fic = @()
            foreach ($fi in @($b.fileIcons | Where-Object { $_ })) {
                $ftarget = ViExpand $fi.installPath.Replace('{installDir}', $installDir)
                $ftemp = $null
                if (-not ((Test-Path -LiteralPath $ftarget) -and ((ViSha $ftarget) -eq $fi.sha256))) {
                    ViInfo "$($fi.file)"
                    $ftemp = Join-Path $tmp $fi.file
                    ViDownload $fi.url $ftemp $fi.file
                    if ((ViSha $ftemp) -ne $fi.sha256) { throw "Checksum mismatch for $($fi.file) downloaded from $($fi.url). Nothing was installed." }
                }
                $fic += [pscustomobject]@{ Target = $ftarget; Temp = $ftemp; Meta = $fi }
            }
            if ($b.kind -eq 'archive') {
                $adir = ViExpand $b.installPath.Replace('{installDir}', $installDir)
                $prev = $null
                if ($old) { $prev = @($old.archives) | Where-Object { $_.name -eq $b.name -and $_.sha256 -eq $b.sha256 -and $_.dir -eq $adir } | Select-Object -First 1 }
                $intact = [bool]$prev
                if ($intact) {
                    foreach ($f in @($old.files)) {
                        if ($f.kind -eq 'archive-file' -and $f.name -eq $b.name -and -not (Test-Path -LiteralPath $f.path)) { $intact = $false; break }
                    }
                }
                if ($intact) {
                    ViInfo "$($b.file) is already current"
                    $staged += [pscustomobject]@{ Bin = $b; Target = $adir; Temp = $null; Extracted = $null; Icon = $null }
                    continue
                }
                ViInfo ("{0} ({1:N1} MB)" -f $b.file, ($b.size / 1MB))
                $dl = Join-Path $tmp $b.file
                ViDownload $b.url $dl $b.file
                if ((ViSha $dl) -ne $b.sha256) { throw "Checksum mismatch for $($b.file) downloaded from $($b.url). Nothing was installed." }
                ViInfo "Unpacking $($b.file)"
                $xdir = Join-Path $tmp ("x-" + $b.name)
                ViExpandZip $dl $xdir
                Remove-Item -Force -LiteralPath $dl
                $staged += [pscustomobject]@{ Bin = $b; Target = $adir; Temp = $null; Extracted = $xdir; Icon = $null }
                continue
            }
            $target = ViExpand $b.installPath.Replace('{installDir}', $installDir)
            if ((Test-Path -LiteralPath $target) -and ((ViSha $target) -eq $b.sha256)) {
                ViInfo "$($b.file) is already current"
                $staged += [pscustomobject]@{ Bin = $b; Target = $target; Temp = $null; Icon = $ic; FileIcons = $fic }
                continue
            }
            ViInfo ("{0} ({1:N1} MB)" -f $b.file, ($b.size / 1MB))
            $dl = Join-Path $tmp $b.file
            ViDownload $b.url $dl $b.file
            if ((ViSha $dl) -ne $b.sha256) { throw "Checksum mismatch for $($b.file) downloaded from $($b.url). Nothing was installed." }
            ViCheckSignature $dl $b.signature $b.file
            $staged += [pscustomobject]@{ Bin = $b; Target = $target; Temp = $dl; Icon = $ic; FileIcons = $fic }
        }
        # 2. place files; from here on the install is not cancelled halfway, and everything it changes goes
        # through the journal (see ViTxBegin) until the commit, so a failure puts the last install back
        ViUiPhase 'busy'
        ViStep "Installing to $installDir"
        $tx = ViTxBegin $id $installDir $tmp
        try {
        ViTxDir $tx $installDir
        $files = @()
        $archives = @()
        foreach ($s in $staged) {
            if ($s.Bin.kind -eq 'archive') {
                ViTxDir $tx $s.Target
                if ($s.Extracted) {
                    $xroot = $s.Extracted.TrimEnd('\')
                    foreach ($f in @(Get-ChildItem -LiteralPath $xroot -Recurse -File -Force)) {
                        $dest = Join-Path $s.Target $f.FullName.Substring($xroot.Length).TrimStart('\')
                        ViTxPut $tx $f.FullName $dest
                        $files += [ordered]@{ path = $dest; kind = 'archive-file'; name = $s.Bin.name; version = $s.Bin.version; sha256 = $null }
                        if ($ViUi -and -not $ViUi.Closed) { [Windows.Forms.Application]::DoEvents() }
                    }
                } else {
                    foreach ($f in @($old.files)) { if ($f.kind -eq 'archive-file' -and $f.name -eq $s.Bin.name) { $files += $f } }
                }
                $archives += [ordered]@{ name = $s.Bin.name; version = $s.Bin.version; sha256 = $s.Bin.sha256; dir = $s.Target }
                continue
            }
            if ($s.Temp) { ViTxPut $tx $s.Temp $s.Target }
            try { Unblock-File -LiteralPath $s.Target } catch { }
            $files += [ordered]@{ path = $s.Target; kind = 'binary'; name = $s.Bin.name; version = $s.Bin.version; sha256 = $s.Bin.sha256 }
            if ($s.Icon) {
                if ($s.Icon.Temp) { ViTxPut $tx $s.Icon.Temp $s.Icon.Target }
                $files += [ordered]@{ path = $s.Icon.Target; kind = 'icon'; name = $s.Bin.name; version = $s.Bin.version; sha256 = $s.Icon.Meta.sha256 }
            }
            foreach ($fi in @($s.FileIcons | Where-Object { $_ })) {
                if ($fi.Temp) { ViTxPut $tx $fi.Temp $fi.Target }
                $files += [ordered]@{ path = $fi.Target; kind = 'file-icon'; name = $s.Bin.name; version = $s.Bin.version; sha256 = $fi.Meta.sha256 }
            }
            if ($s.Bin.kind -eq 'jar') {
                $launcher = ViExpand $s.Bin.launcher.Replace('{installDir}', $installDir)
                ViTxPutText $tx $launcher (ViJarLauncher $s.Bin (Split-Path $s.Target -Leaf))
                $files += [ordered]@{ path = $launcher; kind = 'launcher'; name = $s.Bin.name; version = $s.Bin.version; sha256 = (ViSha $launcher) }
            }
        }
        foreach ($t in $tools) {
            $dest = Join-Path $installDir $t.Name
            if (-not ((Test-Path -LiteralPath $dest) -and (ViSha $dest) -eq $t.Sha)) { ViTxPut $tx $t.Temp $dest }
            $files += [ordered]@{ path = $dest; kind = 'tool'; name = $t.Name; version = $entry.version; sha256 = $t.Sha }
            $wrapper = Join-Path $installDir ($t.Name -replace '\.ps1$', '.cmd')
            $wtext = "@echo off`r`npowershell.exe -NoProfile -ExecutionPolicy Bypass -File `"%~dp0$($t.Name)`" %*`r`nexit /b %errorlevel%`r`n"
            ViTxPutText $tx $wrapper $wtext
            $files += [ordered]@{ path = $wrapper; kind = 'tool'; name = (Split-Path $wrapper -Leaf); version = $entry.version; sha256 = (ViSha $wrapper) }
        }

        # other installs' launchers read this to find this install (see ViJarLauncher)
        $pointer = Join-Path $regDir "$id.home"
        ViTxPutText $tx $pointer "$installDir`r`n"
        $files += [ordered]@{ path = $pointer; kind = 'pointer'; name = "$id.home"; version = $entry.version; sha256 = (ViSha $pointer) }

        # what the last install had and this one does not goes into the backup too, so a rollback restores it
        if ($old) {
            $newPaths = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
            foreach ($nf in $files) { [void]$newPaths.Add([string]$nf.path) }
            foreach ($f in @($old.files)) {
                if ($f.path -and (-not $newPaths.Contains([string]$f.path)) -and (Test-Path -LiteralPath $f.path -PathType Leaf)) { ViTxAside $tx $f.path }
            }
        }

        # 3. shortcuts: written in the temp folder, then put in place like any other file
        $shortcuts = @()
        if (-not $skipShortcuts) {
            foreach ($s in $staged) {
                $sc = $s.Bin.shortcuts
                if (-not $sc) { continue }
                $label = if ($sc.label) { $sc.label } else { $s.Bin.name }
                $target = $s.Target; $sargs = ''
                if ($s.Bin.kind -eq 'jar') {
                    $javaw = if ($sc.gui) { ViJavaw $s.Bin } else { $null }
                    if ($javaw) {
                        $target = $javaw
                        $sargs = (@((ViJvmArgs $s.Bin), "-jar `"$($s.Target)`"") | Where-Object { $_ }) -join ' '
                    }
                    else { $target = ViExpand $s.Bin.launcher.Replace('{installDir}', $installDir) }
                }
                $icon = if ($s.Icon) { $s.Icon.Target } elseif ($s.Bin.kind -eq 'native') { $s.Target } else { $null }
                $places = @()
                if ($sc.desktop) { $places += [Environment]::GetFolderPath('Desktop') }
                if ($sc.startMenu) { $places += [Environment]::GetFolderPath('Programs') }
                foreach ($pl in $places) {
                    $lnk = Join-Path $pl "$label.lnk"
                    $tlnk = Join-Path $tmp ("s-" + [guid]::NewGuid().ToString('N') + '.lnk')
                    ViShortcut $tlnk $target $sargs $installDir "$appName" $icon
                    ViTxPut $tx $tlnk $lnk
                    $shortcuts += $lnk
                    if (-not $ViState.Launch) { $ViState.Launch = $lnk; $ViState.LaunchLabel = $label }
                    ViInfo "Shortcut: $lnk"
                }
            }
        }

        # 4. file associations: the binary gets the file as its last argument
        $associations = @()
        if (-not $skipAssoc) {
            foreach ($s in $staged) {
                if (-not $s.Bin.fileAssociations) { continue }
                $cmd = "`"$($s.Target)`" `"%1`""
                if ($s.Bin.kind -eq 'jar') {
                    $javaw = if (@($s.Bin.fileAssociations)[0].gui) { ViJavaw $s.Bin } else { $null }
                    if ($javaw) { $cmd = ((@("`"$javaw`"", (ViJvmArgs $s.Bin), "-jar `"$($s.Target)`" `"%1`"") | Where-Object { $_ }) -join ' ') }
                    else { $cmd = "`"$(ViExpand $s.Bin.launcher.Replace('{installDir}', $installDir))`" `"%1`"" }
                }
                $icon = if ($s.Icon) { $s.Icon.Target } elseif ($s.Bin.kind -eq 'native') { $s.Target } else { $null }
                foreach ($fa in @($s.Bin.fileAssociations)) {
                    $ficon = $icon
                    if ($fa.icon) {
                        $own = @($s.FileIcons | Where-Object { $_ -and $_.Meta.file -eq $fa.icon }) | Select-Object -First 1
                        if ($own) { $ficon = $own.Target }
                    }
                    try {
                        $had = @($old.fileAssociations | Where-Object { $_ -and $_.progId -eq $fa.progId }).Count -gt 0
                        if (-not $had) { ViTxLog $tx @{ op = 'assoc'; a = [ordered]@{ extension = $fa.extension; progId = $fa.progId; contentType = $null } } }
                        $a = ViAssocAdd $fa $cmd $ficon
                        if (-not $had) { ViTxLog $tx @{ op = 'assoc'; a = $a } }
                        $associations += $a
                        ViInfo ("Opens {0} files{1}" -f $fa.extension, $(if ($a.isDefault) { ' (default)' } else { ' (listed under Open with)' }))
                    } catch { ViWarn "Could not register $($fa.extension): $($_.Exception.Message)" }
                }
            }
        }

        # 5. PATH
        $pathEntries = @()
        if (-not $skipPath) {
            $wanted = @()
            foreach ($s in $staged) {
                if (-not $s.Bin.addToPath) { continue }
                $p = if ($s.Bin.kind -eq 'jar') { ViExpand $s.Bin.launcher.Replace('{installDir}', $installDir) } else { $s.Target }
                $d = Split-Path $p -Parent
                if ($wanted -notcontains $d) { $wanted += $d }
            }
            foreach ($d in $wanted) {
                $onPath = @(([string](ViUserPathGet)) -split ';' | Where-Object { $_ -and (ViPathNorm $_) -eq (ViPathNorm $d) }).Count -gt 0
                if (-not $onPath) { ViTxLog $tx @{ op = 'path'; dir = $d } }
                $added = ViPathAdd $d
                if ($added -or ($old -and (@($old.pathEntries) -contains $d))) { $pathEntries += $d }
                if ($added) { ViInfo "Added to user PATH: $d" }
            }
        }

        # 6. shortcuts the last install made and this one does not
        foreach ($l in @($old.shortcuts)) {
            if ($l -and ($shortcuts -notcontains $l) -and (Test-Path -LiteralPath $l -PathType Leaf)) { ViTxAside $tx $l }
        }

        # 7. install manifest, then the commit
        # `commands` is how other installed programs find and start these binaries without
        # relying on PATH: name -> absolute path to run (the .cmd launcher for a jar).
        $commands = [ordered]@{}
        foreach ($s in $staged) {
            if ($s.Bin.kind -eq 'archive') {
                if ($s.Bin.exposes) {
                    foreach ($cn in $s.Bin.exposes.PSObject.Properties) {
                        $commands[$cn.Name] = [ordered]@{ path = (Join-Path $s.Target $cn.Value); kind = 'native'; version = $s.Bin.version }
                    }
                }
                continue
            }
            if ($s.Bin.kind -eq 'file') { continue }
            $run = if ($s.Bin.kind -eq 'jar') { ViExpand $s.Bin.launcher.Replace('{installDir}', $installDir) } else { $s.Target }
            $commands[$s.Bin.name] = [ordered]@{ path = $run; kind = $s.Bin.kind; version = $s.Bin.version }
        }
        $now = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
        $uninstallKey = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\$id"
        $record = [ordered]@{
            schemaVersion = 1
            id            = $id
            name          = $appName
            publisher     = $InstallerCfg.publisher
            version       = $entry.version
            platform      = 'windows'
            installedAt   = $(if ($old -and $old.installedAt) { $old.installedAt } else { $now })
            updatedAt     = $now
            installDir    = $installDir
            manifestUrl   = $InstallerCfg.manifestUrl
            requires      = @(@($plat.requires.installs) | Where-Object { $_ } | ForEach-Object { $_.id })
            commands      = $commands
            archives      = $archives
            files         = $files
            shortcuts     = $shortcuts
            pathEntries   = $pathEntries
            fileAssociations = $associations
            options       = [ordered]@{ noShortcuts = $skipShortcuts; noPath = $skipPath; noAssociations = $skipAssoc }
            registryKeys  = @($uninstallKey)
        }
        $json = $record | ConvertTo-Json -Depth 10
        ViTxPutText $tx (Join-Path $installDir 'install-manifest.json') $json
        ViTxPutText $tx $recPath $json
        ViTxCommit $tx
        } catch {
            $err = $_.Exception.Message
            $back = ViTxRollback $tx.Journal
            $what = if (-not $back) { 'Not everything could be put back; the next install of it will try again.' }
                    elseif ($old) { "$appName $($old.version) was put back as it was." } else { 'Nothing was left installed.' }
            throw "$err $what"
        }

        # 8. after the commit: what the last install registered and this one does not, and the Apps entry
        if ($old) {
            # an updated archive may have dropped folders; remove the ones left empty
            foreach ($a in $archives) {
                if (-not (Test-Path -LiteralPath $a.dir)) { continue }
                Get-ChildItem -LiteralPath $a.dir -Directory -Recurse -Force |
                    Sort-Object { $_.FullName.Length } -Descending |
                    Where-Object { -not (Get-ChildItem -LiteralPath $_.FullName -Force) } |
                    Remove-Item -Force -ErrorAction SilentlyContinue
            }
            foreach ($d in @($old.pathEntries)) {
                if ($d -and ($pathEntries -notcontains $d)) { ViPathRemove $d }
            }
            $keptProgIds = @($associations | ForEach-Object { $_.progId })
            foreach ($a in @($old.fileAssociations)) {
                if ($a -and $a.progId -and ($keptProgIds -notcontains $a.progId)) {
                    try { ViAssocRemove $a } catch { ViWarn "Could not unregister $($a.extension): $($_.Exception.Message)" }
                }
            }
        }
        if ($associations.Count -gt 0 -or @($old.fileAssociations | Where-Object { $_ }).Count -gt 0) { ViNotifyAssoc }

        New-Item -Path $uninstallKey -Force | Out-Null
        $uninstallCmd = Join-Path $installDir 'uninstall.cmd'
        $icon = ($files | Where-Object { $_.kind -eq 'icon' } | Select-Object -First 1)
        if (-not $icon) { $icon = ($files | Where-Object { $_.kind -eq 'binary' -and $_.path -like '*.exe' } | Select-Object -First 1) }
        $sizeKb = [int]((($files | Where-Object { Test-Path -LiteralPath $_.path } | ForEach-Object { (Get-Item -LiteralPath $_.path).Length } | Measure-Object -Sum).Sum) / 1KB)
        $props = @{
            DisplayName          = $appName
            DisplayVersion       = $entry.version
            Publisher            = $InstallerCfg.publisher
            InstallLocation      = $installDir
            UninstallString      = "`"$uninstallCmd`""
            QuietUninstallString = "`"$uninstallCmd`" -Yes"
            InstallDate          = (Get-Date).ToString('yyyyMMdd')
        }
        if ($icon) { $props.DisplayIcon = $icon.path }
        foreach ($k in $props.Keys) { New-ItemProperty -Path $uninstallKey -Name $k -Value $props[$k] -PropertyType String -Force | Out-Null }
        New-ItemProperty -Path $uninstallKey -Name NoModify -Value 1 -PropertyType DWord -Force | Out-Null
        New-ItemProperty -Path $uninstallKey -Name NoRepair -Value 1 -PropertyType DWord -Force | Out-Null
        New-ItemProperty -Path $uninstallKey -Name EstimatedSize -Value $sizeKb -PropertyType DWord -Force | Out-Null

        ViSay ""
        ViSay "$appName $($entry.version) installed." Green
        ViSay "    Location:  $installDir"
        ViSay "    Manifest:  $recPath"
        ViSay "    Update:    $(Join-Path $installDir 'update.cmd')"
        ViSay "    Uninstall: $uninstallCmd   (or Settings > Apps)"
        if ($tools | Where-Object { $_.Name -eq 'diagnose.ps1' }) { ViSay "    Diagnose:  $(Join-Path $installDir 'diagnose.cmd')   (a report to attach to bug reports)" }
        if ($pathEntries.Count -gt 0) { ViSay "    Open a new terminal for PATH changes to take effect." }
        return $true
    } finally {
        Remove-Item -Recurse -Force -LiteralPath $tmp -ErrorAction SilentlyContinue
    }
}

$ViArgs = @{}
$ViQuiet = $false
if ($env:INSTALL_VERSION) { $ViArgs.Version = $env:INSTALL_VERSION }
if ($env:INSTALL_DIR) { $ViArgs.Dir = $env:INSTALL_DIR }
if ($env:INSTALL_FORCE) { $ViArgs.Force = $true }
for ($ViI = 0; $ViI -lt $args.Count; $ViI++) {
    switch -Regex ($args[$ViI]) {
        '^-Version$' { $ViI++; $ViArgs.Version = $args[$ViI] }
        '^-Dir$' { $ViI++; $ViArgs.Dir = $args[$ViI] }
        '^-NoShortcuts$' { $ViArgs.NoShortcuts = $true }
        '^-NoPath$' { $ViArgs.NoPath = $true }
        '^-NoAssociations$' { $ViArgs.NoAssociations = $true }
        '^-Force$' { $ViArgs.Force = $true }
        '^-SkipChecks$' { $ViArgs.SkipChecks = $true }
        '^-Quiet$' { $ViQuiet = $true }
        default { Write-Warning "Ignoring unknown argument: $($args[$ViI])" }
    }
}
if ($env:INSTALL_SKIP_CHECKS -and $env:INSTALL_SKIP_CHECKS -ne '0') { $ViArgs.SkipChecks = $true }
$ViOk = $false
$ViErr = $null
# what ViInvokeInstall leaves for a failure report (diagnose.ps1's text, and the report if one was written)
# and for the window's last page
$ViState = @{ DiagText = $null; Report = $null; Cancelled = $false; Version = $null; Dir = $null; Launch = $null; LaunchLabel = $null }
$ViUi = $null
if (ViWantsWindow $ViQuiet) {
    try { $ViUi = ViUiOpen } catch { $ViUi = $null; Write-Warning "Could not open the installer window ($($_.Exception.Message)); continuing here." }
}
try {
    $ViOk = [bool](ViInvokeInstall @ViArgs | Select-Object -Last 1)
} catch {
    $ViErr = $_.Exception.Message
    ViSay "ERROR: $ViErr" Red
    if ($ViState.DiagText -and -not $ViState.Report -and -not $ViState.Cancelled) {
        ViSay "Writing a diagnostic report..."
        try { $ViState.Report = (& ([scriptblock]::Create($ViState.DiagText)) -Check -InstallError $ViErr | Select-Object -Last 1).report } catch { }
    }
    if ($ViState.Report) {
        ViSay "Diagnostic report: $($ViState.Report)" Yellow
        if ($InstallerCfg.issuesUrl) { ViSay "To report the problem, attach it at $($InstallerCfg.issuesUrl)" }
    }
} finally {
    if ($ViState.Lock) { $ViState.Lock.Dispose(); $ViState.Lock = $null }
    if ($ViUi) { ViUiFinish $ViOk $ViErr; $ViUi = $null }
}
if (-not $ViOk -and $PSCommandPath) { exit 1 }
